str_prufer <- function(ptree) {
  paste(sprintf("%d", ptree), collapse = ":")
}

  # Step 1: Convert Prufer code to edge list
  prufer_to_tree <- function(code) {
    m <- length(code)
    n <- m + 2
    degree <- rep(1, n)
    for (i in code) degree[i] <- degree[i] + 1
    
    edges <- matrix(ncol = 2, nrow = 0)
    for (i in code) {
      leaf <- which(degree == 1)[1]
      edges <- rbind(edges, c(leaf, i))
      degree[leaf] <- degree[leaf] - 1
      degree[i] <- degree[i] - 1
    }
    u <- which(degree == 1)
    edges <- rbind(edges, u)
    return(edges)
  }


prufer_to_graph <- function(prufer_code) {
  if (!is.numeric(prufer_code)) {
        prufer_code <- strsplit(prufer_code, ":")[[1]] |> as.integer()
  }
  edges <- prufer_to_tree(prufer_code)
  graph_from_edgelist(edges, directed = FALSE)
}

remove_vertex_and_prufer_code <- function(prufer_code, remove_vertex) {
  library(igraph)
  
  
  # Step 2: Convert edge list to graph
  edges <- prufer_to_tree(prufer_code)
  g <- graph_from_edgelist(edges, directed = FALSE)
  
  # Step 3: Remove the vertex
  if (!(remove_vertex %in% V(g))) {
    stop("The vertex to remove does not exist.")
  }
  g <- delete_vertices(g, remove_vertex)
  
  # Step 4: Relabel vertices from 1 to (n-1)
  old_names <- as.numeric(V(g)$name)
  new_labels <- setNames(seq_along(old_names), old_names)
  V(g)$name <- as.character(new_labels[as.numeric(V(g)$name)])
  
  # Update edge list with relabeled nodes
  edges_relabelled <- as_edgelist(g, names = TRUE)
  edges_relabelled <- matrix(as.integer(edges_relabelled), ncol = 2)
  
  # Step 5: Compute new Prufer code
  tree_to_prufer <- function(edge_list, n) {
    deg <- table(factor(c(edge_list), levels = 1:n))
    prufer <- c()
    for (i in 1:(n - 2)) {
      leaves <- which(deg == 1)
      leaf <- min(leaves)
      idx <- which(edge_list[,1] == leaf | edge_list[,2] == leaf)[1]
      edge <- edge_list[idx, ]
      neighbor <- if (edge[1] == leaf) edge[2] else edge[1]
      prufer <- c(prufer, neighbor)
      deg[as.character(leaf)] <- deg[as.character(leaf)] - 1
      deg[as.character(neighbor)] <- deg[as.character(neighbor)] - 1
      edge_list <- edge_list[-idx, , drop = FALSE]
    }
    return(as.integer(prufer))
  }
  
  n_new <- vcount(g)
  return(tree_to_prufer(edges_relabelled, n_new))
}
